@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final RestClient orderServiceRestClient;
    private final KafkaTemplate<String, OrderEvent> kafkaTemplate;

    public OrderController(RestClient.Builder restClientBuilder, KafkaTemplate<String, OrderEvent> kafkaTemplate) {
        this.orderServiceRestClient = restClientBuilder.baseUrl("http://inventory-service").build();
        this.kafkaTemplate = kafkaTemplate;
    }

    @PostMapping
    public ResponseEntity<String> createOrder(@RequestBody OrderRequest request) {
        // Microservices inter-service communication via HTTP / Messaging
        ResponseEntity<InventoryResponse> response = orderServiceRestClient.get()
            .uri("/check/{sku}", request.getSku())
            .retrieve()
            .toEntity(InventoryResponse.class);

        if (response.getBody() == null || !response.getBody().isInStock()) {
            return ResponseEntity.badRequest().body("Item out of stock");
        }

        kafkaTemplate.send("order-events", new OrderEvent(request.getOrderId(), "CREATED"));
        return ResponseEntity.accepted().body("Order processing initiated");
    }
}
